insert into recipe_steps (id, public_id, recipe_id, position, instructions, timer_minutes) values
  ('00000000-0000-4000-8000-000000005001', '01JY8AEJCPS5SQKJN2K2DW40KE', '00000000-0000-4000-8000-000000002001', 1, 'Pat the pork belly and pork tenderloin dry with paper towels and rinse / clean them to remove blood (myoglobin).', null),
  ('00000000-0000-4000-8000-000000005002', '01JY8APVBB9YS93A5F36MZ9442', '00000000-0000-4000-8000-000000002001', 2, 'Grind the pork belly and pork tenderloin.', null),
  ('00000000-0000-4000-8000-000000005003', '01JY8A0HRTZQKKSC8ZEPH7XJ34', '00000000-0000-4000-8000-000000002001', 3, 'Mix the ground meats together to create ground pork with balanced fat from the belly and tenderloin.', null),
  ('00000000-0000-4000-8000-000000005004', '01JY8AC02JKM24F5DWPF1M067M', '00000000-0000-4000-8000-000000002002', 1, 'Mix the ground pork with soy sauce, stirring well so the meat absorbs the flavor.', null),
  ('00000000-0000-4000-8000-000000005005', '01JY8AR5ZX1AXDRD61AE6HMQBX', '00000000-0000-4000-8000-000000002002', 2, 'Add the seasoned ground pork to a bowl.', null),
  ('00000000-0000-4000-8000-000000005006', '01JY8A4A35ZK17JRZE3H4A13XG', '00000000-0000-4000-8000-000000002002', 3, 'Crack the eggs on top of the pork and scatter scallions over them.', null),
  ('00000000-0000-4000-8000-000000005007', '01JY8AAN1SCYEJ3HM8E7CH1SXX', '00000000-0000-4000-8000-000000002002', 4, 'Fill the pot ~1/4 with water and place the bowl in it.', null),
  ('00000000-0000-4000-8000-000000005008', '01JY8ASTEDG75YC45F32ZFHYB4', '00000000-0000-4000-8000-000000002002', 5, 'Cover the pot and steam for 20 minutes.', 20),
  ('00000000-0000-4000-8000-000000005009', '01JY8AYQHNGPS1DX19DYTZ204Z', '00000000-0000-4000-8000-000000002003', 1, 'Heat olive oil in a large pot over medium heat. Add diced onion and cook until softened.', 5),
  ('00000000-0000-4000-8000-000000005010', '01JY8AACPEV3QYT42TY15JFGW2', '00000000-0000-4000-8000-000000002003', 2, 'Add minced garlic and cook until fragrant.', 1),
  ('00000000-0000-4000-8000-000000005011', '01JY8ABRVFXCB6ASEFJKC3QMKH', '00000000-0000-4000-8000-000000002003', 3, 'Pour in crushed tomatoes and vegetable broth. Stir in dried basil and season with salt and pepper.', null),
  ('00000000-0000-4000-8000-000000005012', '01JY8AYDH686M7BWVXN34QKARV', '00000000-0000-4000-8000-000000002003', 4, 'Add quartered potatoes and corn pieces to the pot.', null),
  ('00000000-0000-4000-8000-000000005013', '01JY8ANG3QM3FF3DJV9EEYTY5S', '00000000-0000-4000-8000-000000002003', 5, 'Bring to a boil, then reduce heat and simmer until potatoes are tender.', 33),
  ('00000000-0000-4000-8000-000000005014', '01JY8ADVFZSNV483MCTPMKRRTS', '00000000-0000-4000-8000-000000002003', 6, 'Taste and adjust seasonings. Serve hot with crusty bread!', null);

